<?php require __DIR__.'/head.php'; $isDriver=(int)$driver['account_id']===(int)$user['id'];$isPassenger=(int)$ride['passenger_id']===(int)$user['id'];$unposted=in_array($ride['status'],['draft','ready'],true);$expired=$unposted&&$ride['expires_at']<=Alba\App::now();$draft=$unposted&&!$expired;$programme=Alba\App::one('SELECT * FROM programme WHERE id=1');$estimated=$programme['earning_paused']?0:intdiv(((int)$ride['fare']-(int)$ride['redeemed'])*(int)$rule['earn_bps'],10000); ?>
<main id="main" class="narrow"><a class="back" href="<?=e(url())?>">← Înapoi în cont</a><section class="card"><p class="eyebrow">CONFIRMARE CURSĂ · <?=$expired?'Expirat':state($ride['status'])?></p><h1><?=ron($ride['fare'])?> <small>lei</small></h1><p><?=e($ride['participant_name'])?> · <?=e($ride['vehicle_plate'])?> · Șofer #<?=e($ride['driver_id'])?></p><p>Pasager <?=e(Alba\App::masked($ride['passenger_phone']))?> · Cod <strong><?=e($ride['request_code'])?></strong></p><div class="calculation"><div><span>Tarif eligibil</span><b><?=ron($ride['fare'])?> lei</b></div><div><span>Credit folosit</span><b><?=ron($ride['redeemed'])?> lei</b></div><div class="collect"><span>De încasat</span><strong><?=ron((int)$ride['fare']-(int)$ride['redeemed'])?> lei</strong></div><div><span>Credit câștigat <?=$draft?'(estimare)':''?></span><b><?=$draft?ron($estimated).' lei':ron($ride['earned']).' lei'?></b></div></div><p class="fine">Reguli #<?=e($rule['id'])?> · câștig <?=e($rule['earn_bps']/100)?>% · limită folosire <?=e($rule['cap_bps']/100)?>% · valabil până la <?=e(localtime_ro($ride['expires_at']))?>.</p>
<?php if($draft&&$isPassenger):?><form class="stack" data-command="approve"><input type="hidden" name="ride_id" value="<?=e($ride['id'])?>"><label>Credit pe care aleg să îl folosesc (lei)<input name="amount" inputmode="decimal" value="<?=ron($ride['redeemed'])?>" required></label><button class="button">Aprob suma pentru această cursă</button></form><?php endif ?>
<?php if($draft&&$isDriver):?><div class="alert"><?=$ride['approval']==='approved'?'Pasagerul a aprobat '.ron($ride['redeemed']).' lei.':'Pasagerul poate aproba creditul din contul propriu. Fără aprobare se înregistrează doar o cursă fără credit folosit.'?> Actualizează pagina pentru a vedea aprobarea.</div><div class="actions"><button class="button secondary" data-refresh>Actualizează</button><form data-command="post" data-financial><input type="hidden" name="ride_id" value="<?=e($ride['id'])?>"><button class="button">Confirm cursa efectuată și încasarea</button></form></div><?php endif ?>
<?php if($expired):?><div class="alert error"><b>Confirmarea a expirat.</b> Cursa nu poate fi înregistrată. Închide această confirmare, apoi cere pasagerului să creeze un cod nou.</div><?php endif ?>
<?php if($unposted&&($isDriver||$isPassenger)):?><form data-command="cancel"><input type="hidden" name="ride_id" value="<?=e($ride['id'])?>"><button class="text-button"><?=$expired?'Închide confirmarea expirată':'Anulează această confirmare'?></button></form><?php endif ?>
<?php if($correction):?><div class="alert">Corecție: <?=state($correction['status'])?> · <?=e($correction['reason'])?></div><?php endif ?></section><section class="card"><h2>Înregistrări de credit</h2><?php foreach($ledger as $entry):?><div class="list-row"><span><?=state($entry['kind'])?> · <?=e(localtime_ro($entry['created_at']))?></span><b><?=ron($entry['amount'])?> lei</b></div><?php endforeach ?><?php if(!$ledger):?><p class="empty">Creditul apare numai după înregistrarea cursei.</p><?php endif ?></section>
<?php if($user['is_admin']):?><section class="card"><h2>Verificare administrator</h2><p class="mono"><?=e($ride['id'])?></p><p>Pasager #<?=e($ride['passenger_id'])?> · Afiliere #<?=e($ride['driver_id'])?> · Participant #<?=e($ride['participant_id'])?></p><?php foreach(Alba\App::all('SELECT * FROM fund_entries WHERE ride_id=?',[$ride['id']]) as $entry):?><div class="list-row"><span><?=state($entry['kind'])?></span><b><?=ron($entry['amount'])?> lei</b></div><?php endforeach ?>
<?php if($ride['status']==='posted'&&!$correction):?><form class="stack" data-command="reverse" data-financial><input type="hidden" name="ride_id" value="<?=e($ride['id'])?>"><label>Motiv corecție<textarea name="reason" minlength="5" required></textarea></label><button class="button danger">Înregistrează reversarea</button></form><?php endif ?></section><?php endif ?>
<section class="card"><h2>Ai nevoie de ajutor?</h2><form class="stack" data-command="support"><input type="hidden" name="ride_id" value="<?=e($ride['id'])?>"><label>Descrie problema<textarea name="message" minlength="5" required></textarea></label><button class="button secondary">Trimite sesizarea</button></form></section></main><?php require __DIR__.'/foot.php'; ?>
